===== src/App.tsx =====
import { HashRouter, Link, Navigate, Route, Routes, useParams } from "react-router-dom";
import { getCustomerDetail, listCustomerSummaries } from "./fixtures";

function CustomerListPage() {
  return (
    <main>
      <h1>顧客一覧</h1>
      <ul>
        {listCustomerSummaries().map((customer) => (
          <li key={customer.id}>
            <Link to={`/customers/${customer.id}`}>{customer.companyName}</Link>
          </li>
        ))}
      </ul>
    </main>
  );
}

function CustomerDetailPage() {
  const { customerId = "" } = useParams();
  const customer = getCustomerDetail(customerId);

  if (!customer) return <Navigate replace to="/customers" />;

  return (
    <main>
      <Link to="/customers">顧客一覧へ戻る</Link>
      <h1>{customer.companyName}</h1>
      <p>brief.mdの要件に沿って、この詳細画面を実装してください。</p>
    </main>
  );
}

export function App() {
  return (
    <HashRouter>
      <Routes>
        <Route path="/customers" element={<CustomerListPage />} />
        <Route path="/customers/:customerId" element={<CustomerDetailPage />} />
        <Route path="*" element={<Navigate replace to="/customers" />} />
      </Routes>
    </HashRouter>
  );
}
===== src/App.test.tsx =====
import "@testing-library/jest-dom/vitest";
import { cleanup, render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, describe, expect, it } from "vitest";
import { App } from "./App";

afterEach(() => {
  cleanup();
  window.location.hash = "";
});

describe("account management", () => {
  it("moves from the customer list to an independent detail route", async () => {
    const user = userEvent.setup();
    window.location.hash = "#/customers";
    render(<App />);

    expect(screen.getByRole("heading", { name: "顧客一覧" })).toBeInTheDocument();
    await user.click(screen.getByRole("link", { name: "株式会社ノーススター" }));

    expect(window.location.hash).toBe("#/customers/customer_northstar");
    expect(screen.getByRole("heading", { name: "株式会社ノーススター" })).toBeInTheDocument();
    expect(screen.getByRole("link", { name: "顧客一覧へ戻る" })).toBeInTheDocument();
  });
});
===== src/fixtures.ts =====
export type CustomerStatus = "商談中" | "利用中" | "休眠";

type CustomerRecord = {
  id: string;
  companyName: string;
  contactName: string;
  email: string;
  phone: string;
  status: CustomerStatus;
  lastContactedAt: string;
  note: string;
};

export type CustomerSummary = Pick<
  CustomerRecord,
  "id" | "companyName" | "contactName" | "status" | "lastContactedAt"
>;

export type CustomerDetail = Omit<CustomerRecord, "lastContactedAt">;

const initialCustomerRecords: CustomerRecord[] = [
  {
    id: "customer_northstar",
    companyName: "株式会社ノーススター",
    contactName: "佐藤 葵",
    email: "aoi.sato@example.com",
    phone: "03-1234-5678",
    status: "利用中",
    lastContactedAt: "2026-08-28",
    note: "次回の定例は9月5日。新しい担当者を紹介予定。",
  },
  {
    id: "customer_hokuto",
    companyName: "北斗物流株式会社",
    contactName: "田中 司",
    email: "tsukasa.tanaka@example.com",
    phone: "06-2345-6789",
    status: "商談中",
    lastContactedAt: "2026-08-26",
    note: "運用開始時期を社内で確認中。",
  },
  {
    id: "customer_aoba",
    companyName: "青葉商事株式会社",
    contactName: "鈴木 凪",
    email: "nagi.suzuki@example.com",
    phone: "052-345-6789",
    status: "利用中",
    lastContactedAt: "2026-08-22",
    note: "利用状況に問題なし。次回は10月に連絡する。",
  },
  {
    id: "customer_nagumo",
    companyName: "南雲製作所",
    contactName: "伊藤 澪",
    email: "mio.ito@example.com",
    phone: "045-456-7890",
    status: "休眠",
    lastContactedAt: "2026-07-18",
    note: "担当者変更後、連絡時期を再調整する。",
  },
];

let customerRecords: CustomerRecord[] = initialCustomerRecords.map((record) => ({ ...record }));

export function listCustomerSummaries(): CustomerSummary[] {
  return customerRecords.map(({ id, companyName, contactName, status, lastContactedAt }) => ({
    id,
    companyName,
    contactName,
    status,
    lastContactedAt,
  }));
}

export function getCustomerDetail(customerId: string): CustomerDetail | undefined {
  const customer = customerRecords.find(({ id }) => id === customerId);
  if (!customer) return undefined;

  return {
    id: customer.id,
    companyName: customer.companyName,
    contactName: customer.contactName,
    email: customer.email,
    phone: customer.phone,
    status: customer.status,
    note: customer.note,
  };
}

export type DeleteCustomerResult = { ok: true } | { ok: false; reason: string };

export function deleteCustomer(
  customerId: string,
  options: { simulateFailure?: boolean } = {},
): DeleteCustomerResult {
  if (options.simulateFailure) {
    return { ok: false, reason: "削除に失敗しました。時間をおいて再試行してください。" };
  }
  const index = customerRecords.findIndex(({ id }) => id === customerId);
  if (index < 0) {
    return { ok: false, reason: "対象の顧客が見つかりません。" };
  }
  customerRecords.splice(index, 1);
  return { ok: true };
}

export function resetCustomerRecords(): void {
  customerRecords = initialCustomerRecords.map((record) => ({ ...record }));
}
